script:
html { scroll-behavior: smooth; }
::selection { background: #34D399; color: #07100C; }

html.up-js .up-rise { opacity: 0; transform: translateY(20px); }
html.up-js .up-rise.up-in {
  opacity: 1; transform: none;
  transition: opacity 0.85s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.85s cubic-bezier(0.22, 1, 0.36, 1);
}
html.up-js .up-d1.up-in { transition-delay: 0.12s; }
html.up-js .up-d2.up-in { transition-delay: 0.24s; }

.up-grow { flex-grow: 1; flex-shrink: 1; min-width: 0; }

.up-nl { transition: color 0.25s ease; }
.up-nl:hover { color: #E9EDF6; }

.up-btn { transition: transform 0.25s ease, box-shadow 0.25s ease,
  filter 0.25s ease; }
.up-btn:hover { transform: translateY(-2px); filter: brightness(1.08);
  box-shadow: 0 10px 28px rgba(52, 211, 153, 0.28); }
.up-btn-o { transition: border-color 0.25s ease, transform 0.25s ease,
  background-color 0.25s ease; }
.up-btn-o:hover { background-color: rgba(52, 211, 153, 0.06);
  border-color: #34D399; transform: translateY(-2px); }

.up-panel { transition: transform 0.35s cubic-bezier(0.22, 1, 0.36, 1),
  border-color 0.35s ease, box-shadow 0.35s ease; }
.up-panel:hover { border-color: #3A4666; transform: translateY(-4px);
  box-shadow: 0 20px 44px rgba(0, 0, 0, 0.35); }

.up-arrow { transition: letter-spacing 0.3s ease; }
.up-arrow:hover { letter-spacing: 0.04em; }

@keyframes up-pulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(52, 211, 153, 0.5); }
  60% { box-shadow: 0 0 0 7px rgba(52, 211, 153, 0); }
}
html.up-js .up-pulse { animation: up-pulse 2.2s ease-out infinite; }

@keyframes up-blink { 0%, 55% { opacity: 1; } 56%, 100% { opacity: 0; } }
html.up-js .up-cursor { animation: up-blink 1.1s steps(1) infinite; }

html.up-js .up-tick { opacity: 0; transform: scaleY(0.4);
  transform-origin: bottom; }
html.up-js .up-tick.up-in { opacity: 1; transform: none;
  transition: opacity 0.4s ease, transform 0.5s
    cubic-bezier(0.22, 1, 0.36, 1); }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  html.up-js .up-pulse, html.up-js .up-cursor { animation: none; }
}
